using Microsoft.Data.SqlClient;using Microsoft.Extensions.Diagnostics.HealthChecks;namespace WhatsBiz.Api.Health;public sealed class DatabaseHealthCheck(IConfiguration configuration):IHealthCheck{public async Task<HealthCheckResult>CheckHealthAsync(HealthCheckContext context,CancellationToken cancellationToken=default){try{await using var connection=new SqlConnection(configuration.GetConnectionString("DefaultConnection"));await connection.OpenAsync(cancellationToken);await using var command=new SqlCommand("SELECT 1",connection){CommandTimeout=5};await command.ExecuteScalarAsync(cancellationToken);return HealthCheckResult.Healthy("SQL Server is reachable.");}catch(Exception exception){return HealthCheckResult.Unhealthy("SQL Server is unavailable.",exception);}}}
